WITH ba_with_dist AS (
    SELECT beneopsref, bene_dist_ref, bene_feedbackscore, distequityidx
    FROM beneficiariesandassessments
),
benefit_agg AS (
    SELECT beneopsref, AVG(bene_feedbackscore) as avg_bf, AVG(distequityidx) as avg_de
    FROM ba_with_dist
    GROUP BY beneopsref
)
SELECT * FROM benefit_agg WHERE avg_bf IS NOT NULL LIMIT 5;

WITH coord_agg AS (
    SELECT coordopsref, AVG(report_compliance + (stakeholder_satisf * 20) + (dataqualityvalue * 20)) / 3.0 as cqi_score
    FROM coordinationandevaluation
    GROUP BY coordopsref
),
scores AS (
    SELECT coordopsref as opsregistry, ROUND(CAST(cqi_score AS numeric), 2) as cqi
    FROM coord_agg
)
SELECT COUNT(*) FROM scores WHERE cqi > 75;

WITH coord_agg AS (
    SELECT coordopsref, AVG(report_compliance + (stakeholder_satisf * 20) + (dataqualityvalue * 20)) / 3.0 as cqi_score
    FROM coordinationandevaluation
    GROUP BY coordopsref
),
scores AS (
    SELECT coordopsref as opsregistry, ROUND(CAST(cqi_score AS numeric), 2) as cqi
    FROM coord_agg
)
SELECT * FROM scores WHERE cqi > 75 ORDER BY cqi DESC;
